from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import EnterpriseAsset, ClassifiedSoftwareAsset
from .serializers import AssetPolymorphicSerializer

class AssetDetailView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, asset_id):
        try:
            asset = EnterpriseAsset.objects.get(id=asset_id)
        except EnterpriseAsset.DoesNotExist:
            return Response({'error': 'Asset not found'}, status=status.HTTP_404_NOT_FOUND)

        if asset.organization != request.user.organization:
            return Response({'error': 'Forbidden'}, status=status.HTTP_403_FORBIDDEN)

        # Inspect polymorphic subclass to verify specialized authorization
        if isinstance(asset, ClassifiedSoftwareAsset) and not getattr(request.user, 'has_clearance', False):
            return Response({'error': 'Specialized security clearance required for classified software assets'}, status=status.HTTP_403_FORBIDDEN)

        serializer = AssetPolymorphicSerializer(asset)
        return Response(serializer.data)
